// Compose: intercept Back only while you genuinely want it
@Composable
fun EditorScreen(hasUnsavedChanges: Boolean, onDiscard: () -> Unit) {
  var confirming by remember { mutableStateOf(false) }
  BackHandler(enabled = hasUnsavedChanges) { confirming = true }
  if (confirming) DiscardDialog(onConfirm = onDiscard, onDismiss = { confirming = false })
}

// Views: the dispatcher, not the deprecated onBackPressed()
private val backCallback = object : OnBackPressedCallback(false) {
  override fun handleOnBackPressed() { showDiscardDialog() }
}
onBackPressedDispatcher.addCallback(this, backCallback)
backCallback.isEnabled = hasUnsavedChanges          // toggle, do not decide inside

// Predictive back: follow the gesture, then commit or cancel
PredictiveBackHandler(enabled = sheetOpen) { progress ->
  try {
    progress.collect { event -> offset = event.progress }
    closeSheet()
  } catch (cancelled: CancellationException) {
    offset = 0f
  }
}

